/* From Uiverse.io by Satwinder04 - Tags: button */
.__UIV_SCOPE__ .complex-button {
  background-color: #fa4545;
 /* Green */
  border: none;
  color: white;
  padding: 15px 32px;
  text-align: center;
  text-decoration: none;
  display: inline-block;
  font-size: 16px;
  margin: 4px 2px;
  cursor: pointer;
  position: relative;
  overflow: hidden;
  /* border-radius: 10px; */
}

.__UIV_SCOPE__ .complex-button::before {
  content: "";
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background-color: rgba(255, 255, 255, 0.2);
  transform: skewX(-30deg);
  transition: all 1s ease-in-out;
}

.__UIV_SCOPE__ .complex-button:hover::before {
  left: 100%;
}

.__UIV_SCOPE__ .complex-button::after {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 0%;
  height: 100%;
  background-color: rgba(255, 255, 255, 0.5);
  transition: all 0.5s ease-in-out;
}

.__UIV_SCOPE__ .complex-button:hover::after {
  width: 100%;
}

.__UIV_SCOPE__ .complex-button span {
  position: relative;
  z-index: 1;
}

.__UIV_SCOPE__ .complex-button:hover {
  color: #ffffff;
  background-color: #fa4545;
}
